/** 種類名 → 画像。絵のない種は見た目の近い種を流用する */
/**
 * 種類 → イラスト。専用の絵がない種類は、シルエットが最も近い種類の絵を借りる。
 * 借り物であることを忘れないよう、専用絵を持つものを上に、代用を下にまとめてある。
 */
const SPECIES_IMAGE: Record<string, string> = {
  // 専用のイラストがある種類
  "オオクワガタ": SP.ookuwa,
  "ヒラタクワガタ": SP.hirata,
  "コクワガタ": SP.kokuwa,
  "ノコギリクワガタ": SP.nokogiri,
  "ミヤマクワガタ": SP.miyama,
  "ニジイロクワガタ": SP.nijiiro,
  "タランドゥスオオツヤクワガタ": SP.tarandus,
  "オウゴンオニクワガタ": SP.ougononi,
  "パラワンオオヒラタ": SP.parawan,
  "スマトラオオヒラタ": SP.sumatra,
  "アルキデスヒラタクワガタ": SP.alcides,
  "マンディブラリスフタマタクワガタ": SP.mandi,
  "セアカフタマタクワガタ": SP.seaka,
  "メタリフェルホソアカクワガタ": SP.metalli,
  "ギラファノコギリクワガタ": SP.giraffa,
  "パプアキンイロクワガタ": SP.papua,
  "ダイオウヒラタクワガタ": SP.daiou,
  "ヒメオオクワガタ": SP.himeoo,
  "アンタエウスオオクワガタ": SP.antaeus,
  "ネブトクワガタ": SP.nebuto,
  "アカアシクワガタ": SP.akaashi,
  "インターメディアツヤクワガタ": SP.intermedia,

  // 近縁種の絵を借りているもの (専用イラストができ次第ここから外す)
  "ホペイオオクワガタ": SP.ookuwa,
  "タイワンオオクワガタ": SP.ookuwa,
  "レギウスオオツヤクワガタ": SP.tarandus,
};

export function speciesImage(species: string): string {
  return SPECIES_IMAGE[species] ?? SP.ookuwa;
}

